for cid,name,desc,values,bounds,facts,assumptions,not_app in [
 ('c0191','Troika (the Matryoshka investigation)',
 '''The identified Troika description concerns Russian cosmonauts investigating a Matryoshka construct. The archive also discusses other Reynolds works, so adjacent Mechanism wording cannot establish a Mechanism-dominated Earth in this story. The completed comparison concerns the actual research mission rather than an invented social order assembled from neighboring descriptions.

 The guarantee best guess allows conditional mission support, control is a broad human-institutional analogy and the central nonworking scenario is zero for active assigned investigators doing useful research. It is not a civilization-wide labor census. Advanced artifacts and a visitor’s life support do not by themselves establish an ordinary resident distribution economy. This stays outside the society count for the identified investigation scope and corrected discovery identity, not because an exact welfare charter could not be found. The source limitation is preserved explicitly without requiring a full novella read or calling an uncertain adjacent label canonical fact.''',
 (.3,.1,0),([-.85,.98],[-.85,.9],[0,.85]),['The identified description concerns cosmonauts investigating the Matryoshka; the archive lists multiple Reynolds works.'],['The active investigation is the selected mechanism.','Adjacent work descriptions are not imported as this story’s government.'],None),
 ('c0194','Galactic North (the expanding Greenfly ecology)',
 '''Greenfly expands through machine-supported biospheres while humans flee and some scans remain preserved. The selected unit is the expansion ecology, not a resident human support society or a demonstrated civilian robot community. The completed comparison therefore does not score displaced people, empty habitats or stored scans as nonworking beneficiaries.

 Secure human support is extremely weak by analogy and practical expansion control is autonomous machinery. The nonworking axis is inapplicable because the selected ecological unit has no identified active civilian recipient-person cohort. This does not assume artificial awareness is impossible, only that replication and vegetated habitats do not supply a person census. The surviving Conjoiner group is a different population and is not silently equated with the Greenfly system. The case stays outside the society count for its expansion-ecology scope, not a demand for fictional household law. Human extinction or flight never becomes one hundred percent leisure.''',
 (.98,-1,None),([.8,1],[-1,-.9],None),['Greenfly expands, humans flee, scans are preserved and a surviving Conjoiner group is distinct.'],['The selected ecological unit is separate from active human survivors.','Replication and stored scans are not an active civilian person census.'],{'nonworking':'No identified active civilian recipient-person cohort in the selected Greenfly expansion ecology; fugitives, equipment and inactive scans are different units.'}),
]:
 d=deepcopy(D['decisions'][cid]);ca=dict(name=name,media=['book'],scope='The corrected research-mission or expansion-ecology mechanism, not a shared civilian allocation institution',axis=dict(zip(('guarantees','control','nonworking'),values)),intervals=dict(zip(('guarantees','control','nonworking'),bounds)),confidence='low',canon_facts=facts,editorial_assumptions=assumptions,source_ids=d['source_ids'],counted_toward_goal=False)
 if not_app:ca['not_applicable_axes']=not_app
 d.update(status='boundary_case',current_policy_review=True,reassessed_on=DATE,assessment_mode='best_guess',reason='Completed identified-mechanism comparison; no unresolved household-law hold.',analysis=desc,comparison_assessment=ca,follow_up='Completed current-policy comparison; no deep reading required.');changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
